/**
 * What the assistant knows how to answer when it is asked in words, and the step-by-step guides of the Help: one entry per task a person asks for, with the words that say it (`kw`, in
 * every language, separated by "|": a word matches the start of a word of the question, a Japanese or Chinese term matches anywhere), a sample question (`q`, shown as a suggestion) and
 * the steps (`a`, one numbered step per line). Every list is in the order English, Spanish, German, French, Italian, Japanese, Chinese, Portuguese. The Help text of every tab is searched
 * as well (engine.ts), so what is not here is still answered from the Help.
 * `view` is where the task is done: the id of a Dashboard tab, or "settings" for the Config window.
 * Copyright (C) 2026 JuanenRac (Electro Hobby 3D). GPL-3.0
 */
export type Locale = "en" | "es" | "de" | "fr" | "it" | "ja" | "zh" | "pt";
export type Eight = readonly [string, string, string, string, string, string, string, string];
export type Level = "basic" | "advanced" | "technical";
export type Topic = { id: string; view: string; level: Level; kw: Eight; q: Eight; a: Eight };

export const TOPICS: readonly Topic[] = [
  { id: "controller", view: "settings", level: "basic",
    kw: ["add a controller|add controller|find the board|auto search|connect to the board|new controller", "anadir un controlador|agregar controlador|buscar la placa|busqueda automatica|conectar con la placa|nuevo controlador", "controller hinzufugen|platine suchen|automatische suche|mit der platine verbinden|neuer controller", "ajouter un controleur|chercher la carte|recherche automatique|se connecter a la carte|nouveau controleur", "aggiungere un controller|cercare la scheda|ricerca automatica|collegarsi alla scheda|nuovo controller", "コントローラを追加|ボードを探|自動検索|ボードに接続", "添加控制器|查找主板|自动搜索|连接主板|新建控制器", "adicionar um controlador|procurar a placa|pesquisa automatica|ligar a placa|novo controlador"],
    q: ["How do I add a controller?", "¿Cómo añado un controlador?", "Wie füge ich einen Controller hinzu?", "Comment ajouter un contrôleur ?", "Come aggiungo un controller?", "コントローラを追加するには？", "怎么添加控制器？", "Como adiciono um controlador?"],
    a: ["1. Open Config (top bar) > Controllers.\n2. Press \"Add Node\" and enter the name and IP address of the board.\n3. Select the controller in the top-right selector.\n4. Everything you configure is saved on the server and shared by every browser.",
        "1. Abre Config (barra superior) > Controladores.\n2. Pulsa \"Añadir Nodo\" e introduce el nombre y la dirección IP de la placa.\n3. Selecciona el controlador en el selector de arriba a la derecha.\n4. Todo lo que configures se guarda en el servidor y lo comparten todos los navegadores.",
        "1. Config (obere Leiste) > Controller öffnen.\n2. \"Knoten Hinzufügen\" drücken und Name und IP-Adresse der Platine eingeben.\n3. Den Controller im Auswahlfeld oben rechts wählen.\n4. Alles, was Sie einstellen, wird auf dem Server gespeichert und von allen Browsern geteilt.",
        "1. Ouvrez Config (barre du haut) > Contrôleurs.\n2. Appuyez sur « Ajouter un Nœud » et saisissez le nom et l'adresse IP de la carte.\n3. Choisissez le contrôleur dans le sélecteur en haut à droite.\n4. Tout ce que vous configurez est enregistré sur le serveur et partagé par tous les navigateurs.",
        "1. Apri Config (barra in alto) > Controller.\n2. Premi \"Aggiungi Nodo\" e inserisci nome e indirizzo IP della scheda.\n3. Seleziona il controller nel selettore in alto a destra.\n4. Tutto ciò che configuri è salvato sul server e condiviso da tutti i browser.",
        "1. 上部バーの設定 > コントローラを開きます。\n2. 「ノードを追加」を押し、ボードの名前とIPアドレスを入力します。\n3. 右上のセレクターでコントローラを選びます。\n4. 設定はすべてサーバーに保存され、すべてのブラウザで共有されます。",
        "1. 打开顶部栏的“配置 > 控制器”。\n2. 点击“添加节点”，输入主板的名称和 IP 地址。\n3. 在右上角的选择器中选中该控制器。\n4. 你的所有配置都保存在服务器上，并由所有浏览器共享。",
        "1. Abra Config (barra superior) > Controladores.\n2. Prima \"Adicionar nó\" e introduza o nome e o endereço IP da placa.\n3. Selecione o controlador no seletor do canto superior direito.\n4. Tudo o que configurar fica guardado no servidor e é partilhado por todos os navegadores."] },
  { id: "addrobot", view: "overview", level: "basic",
    kw: ["add a robot|add robot|new robot|attach a robot|create a robot", "anadir un robot|agregar robot|nuevo robot|crear un robot|conectar un robot", "roboter hinzufugen|neuer roboter|roboter anlegen", "ajouter un robot|nouveau robot|creer un robot", "aggiungere un robot|nuovo robot|creare un robot", "ロボットを追加|新しいロボット|ロボットを作", "添加机器人|新建机器人|创建机器人", "adicionar um robo|novo robo|criar um robo"],
    q: ["How do I add a robot?", "¿Cómo añado un robot?", "Wie füge ich einen Roboter hinzu?", "Comment ajouter un robot ?", "Come aggiungo un robot?", "ロボットを追加するには？", "怎么添加机器人？", "Como adiciono um robô?"],
    a: ["1. Select the controller the robot belongs to.\n2. Each controller lists its robot slots in the sidebar: click the one you want to set up.\n3. Its control panel opens.\n4. Choose its model and tool in the panel's Model & Tools settings.",
        "1. Selecciona el controlador al que pertenece el robot.\n2. Cada controlador muestra sus robots en la barra lateral: haz clic en el que quieras configurar.\n3. Se abre su panel de control.\n4. Elige su modelo y su herramienta en los ajustes Modelo y herramientas del panel.",
        "1. Den Controller wählen, zu dem der Roboter gehört.\n2. Jeder Controller listet seine Roboter in der Seitenleiste: den gewünschten anklicken.\n3. Sein Bedienfeld öffnet sich.\n4. Modell und Werkzeug in den Einstellungen Modell & Werkzeuge des Bedienfelds wählen.",
        "1. Choisissez le contrôleur auquel appartient le robot.\n2. Chaque contrôleur liste ses robots dans la barre latérale : cliquez sur celui à configurer.\n3. Son panneau de commande s'ouvre.\n4. Choisissez son modèle et son outil dans les réglages Modèle et outils du panneau.",
        "1. Seleziona il controller a cui appartiene il robot.\n2. Ogni controller elenca i suoi robot nella barra laterale: fai clic su quello da configurare.\n3. Si apre il suo pannello di controllo.\n4. Scegli modello e utensile nelle impostazioni Modello e utensili del pannello.",
        "1. ロボットが属するコントローラを選びます。\n2. 各コントローラのロボットはサイドバーに並んでいます。設定したいロボットをクリックします。\n3. 制御パネルが開きます。\n4. パネルのモデルとツールの設定でモデルとツールを選びます。",
        "1. 选中机器人所属的控制器。\n2. 每个控制器的机器人都列在侧边栏中，点击要设置的那一个。\n3. 它的控制面板随即打开。\n4. 在面板的“型号与工具”设置中选择型号和工具。",
        "1. Selecione o controlador a que o robô pertence.\n2. Cada controlador lista os seus robôs na barra lateral: clique no que quer configurar.\n3. O seu painel de controlo abre-se.\n4. Escolha o modelo e a ferramenta nas definições Modelo e ferramentas do painel."] },
  { id: "jog", view: "robot", level: "basic",
    kw: ["move the robot|jog|move a joint|move the arm|joint slider|home the robot", "mover el robot|mover una articulacion|mover el brazo|deslizador|llevar a casa|home", "roboter bewegen|gelenk bewegen|arm bewegen|schieberegler|referenzfahrt", "deplacer le robot|bouger une articulation|bouger le bras|curseur|mise a l origine", "muovere il robot|muovere un giunto|muovere il braccio|cursore|riportare a casa", "ロボットを動か|関節を動か|アームを動か|ジョグ|ホーム", "移动机器人|移动关节|移动机械臂|点动|回零", "mover o robo|mover uma articulacao|mover o braco|deslizador|levar a casa"],
    q: ["How do I move the robot?", "¿Cómo muevo el robot?", "Wie bewege ich den Roboter?", "Comment déplacer le robot ?", "Come muovo il robot?", "ロボットを動かすには？", "怎么移动机器人？", "Como movo o robô?"],
    a: ["1. Click the robot in the sidebar to open its panel.\n2. Drag a joint's knob or slider (J1-J6): the 3D view follows at once and the real arm moves with it.\n3. Press HOME to send the arm to its safe reference pose.\n4. If anything looks wrong, press STOP (red button in the top bar): it halts every robot immediately.",
        "1. Haz clic en el robot de la barra lateral para abrir su panel.\n2. Arrastra el mando o el deslizador de una articulación (J1-J6): la vista 3D lo sigue al instante y el brazo real se mueve con ella.\n3. Pulsa HOME para llevar el brazo a su pose de referencia segura.\n4. Si algo no cuadra, pulsa STOP (botón rojo de la barra superior): detiene todos los robots de inmediato.",
        "1. Den Roboter in der Seitenleiste anklicken, um sein Bedienfeld zu öffnen.\n2. Den Drehknopf oder Schieberegler eines Gelenks (J1-J6) ziehen: die 3D-Ansicht folgt sofort und der echte Arm bewegt sich mit.\n3. HOME drücken, um den Arm in seine sichere Referenzpose zu fahren.\n4. Bei jedem Zweifel STOP drücken (roter Knopf in der oberen Leiste): hält sofort alle Roboter an.",
        "1. Cliquez sur le robot dans la barre latérale pour ouvrir son panneau.\n2. Faites glisser le bouton ou le curseur d'une articulation (J1-J6) : la vue 3D suit aussitôt et le vrai bras bouge avec elle.\n3. Appuyez sur HOME pour envoyer le bras à sa pose de référence sûre.\n4. En cas de doute, appuyez sur STOP (bouton rouge de la barre du haut) : il arrête immédiatement tous les robots.",
        "1. Fai clic sul robot nella barra laterale per aprire il suo pannello.\n2. Trascina la manopola o il cursore di un giunto (J1-J6): la vista 3D lo segue subito e il braccio reale si muove con essa.\n3. Premi HOME per portare il braccio nella sua posa di riferimento sicura.\n4. Se qualcosa non va, premi STOP (pulsante rosso nella barra in alto): ferma subito tutti i robot.",
        "1. サイドバーのロボットをクリックしてパネルを開きます。\n2. 関節（J1〜J6）のノブかスライダーをドラッグします。3Dビューがすぐに追従し、実機のアームも動きます。\n3. HOME を押すと、アームが安全な基準姿勢に移動します。\n4. おかしいと思ったら STOP（上部バーの赤いボタン）を押します。全ロボットがすぐに止まります。",
        "1. 点击侧边栏中的机器人，打开它的面板。\n2. 拖动某个关节（J1-J6）的旋钮或滑块：3D 视图立即跟随，真实机械臂也随之运动。\n3. 点击 HOME，让机械臂回到安全的参考姿态。\n4. 有任何异常，点击 STOP（顶部栏的红色按钮）：所有机器人会立即停止。",
        "1. Clique no robô na barra lateral para abrir o seu painel.\n2. Arraste o botão ou o deslizador de uma articulação (J1-J6): a vista 3D acompanha de imediato e o braço real move-se com ela.\n3. Prima HOME para levar o braço à sua pose de referência segura.\n4. Se algo parecer errado, prima STOP (botão vermelho da barra superior): pára todos os robôs de imediato."] },
  { id: "estop", view: "robot", level: "basic",
    kw: ["emergency stop|e-stop|estop|stop everything|halt|panic", "parada de emergencia|paro de emergencia|e-stop|parar todo|detener", "notaus|not-halt|alles stoppen|anhalten", "arret d urgence|e-stop|tout arreter|arreter", "arresto di emergenza|e-stop|fermare tutto|fermare", "非常停止|緊急停止|e-stop|すべて止め", "紧急停止|急停|全部停止|停止所有", "paragem de emergencia|e-stop|parar tudo|parar"],
    q: ["How do I stop the robot in an emergency?", "¿Cómo paro el robot en una emergencia?", "Wie stoppe ich den Roboter im Notfall?", "Comment arrêter le robot en urgence ?", "Come fermo il robot in emergenza?", "緊急時にロボットを止めるには？", "紧急情况下怎么停止机器人？", "Como paro o robô numa emergência?"],
    a: ["1. Press STOP (the red button in the top bar, also in the robot's panel and in the footer) or Ctrl+Shift+Space: every robot of the cell halts at once, with no confirmation, and all valves and pumps switch off.\n2. The result is listed robot by robot. A warning stays on screen if a robot did not stop or the stop could not be saved, and \"STOP not confirmed\" stays until a later STOP gets an answer.\n3. A gamepad button can be mapped to STOP in Config > Gamepad.\n4. STOP is software: it does not replace the physical emergency stop of the machine.",
        "1. Pulsa STOP (el botón rojo de la barra superior, también en el panel del robot y en el pie) o Ctrl+Shift+Espacio: todos los robots de la célula se detienen al instante, sin confirmación, y todas las válvulas y bombas se apagan.\n2. El resultado se lista robot a robot. Si un robot no se detuvo o la parada no se pudo guardar queda un aviso en pantalla, y «STOP no confirmado» permanece hasta que un STOP posterior obtenga respuesta.\n3. Puedes asignar un botón del mando a STOP en Config > Mando.\n4. STOP es software: no sustituye la parada de emergencia física de la máquina.",
        "1. STOP drücken (der rote Knopf in der oberen Leiste, auch im Bedienfeld des Roboters und in der Fußzeile) oder Strg+Umschalt+Leertaste: alle Roboter der Zelle halten sofort an, ohne Bestätigung, und alle Ventile und Pumpen schalten ab.\n2. Das Ergebnis wird Roboter für Roboter aufgelistet. Ein Warnhinweis bleibt stehen, wenn ein Roboter nicht anhielt oder der Stopp nicht gespeichert werden konnte, und „STOP nicht bestätigt“ bleibt, bis ein späterer STOP eine Antwort bekommt.\n3. Eine Gamepad-Taste lässt sich unter Config > Gamepad auf STOP legen.\n4. STOP ist Software: es ersetzt nicht den physischen Not-Halt der Maschine.",
        "1. Appuyez sur STOP (le bouton rouge de la barre du haut, aussi dans le panneau du robot et dans le pied de page) ou sur Ctrl+Maj+Espace : tous les robots de la cellule s'arrêtent aussitôt, sans confirmation, et toutes les vannes et pompes se coupent.\n2. Le résultat est listé robot par robot. Un avertissement reste affiché si un robot ne s'est pas arrêté ou si l'arrêt n'a pas pu être enregistré, et « STOP non confirmé » reste jusqu'à ce qu'un STOP ultérieur reçoive une réponse.\n3. Un bouton de manette peut être associé à STOP dans Config > Manette.\n4. STOP est logiciel : il ne remplace pas l'arrêt d'urgence physique de la machine.",
        "1. Premi STOP (il pulsante rosso nella barra in alto, anche nel pannello del robot e nel piè di pagina) o Ctrl+Maiusc+Spazio: tutti i robot della cella si fermano subito, senza conferma, e tutte le valvole e pompe si spengono.\n2. Il risultato è elencato robot per robot. Resta un avviso a schermo se un robot non si è fermato o l'arresto non è stato salvato, e «STOP non confermato» resta finché uno STOP successivo non riceve risposta.\n3. Un pulsante del gamepad può essere assegnato a STOP in Config > Gamepad.\n4. STOP è software: non sostituisce l'arresto di emergenza fisico della macchina.",
        "1. STOP（上部バーの赤いボタン。ロボットのパネルとフッターにもあります）または Ctrl+Shift+Space を押すと、セル内のすべてのロボットが確認なしですぐに停止し、すべてのバルブとポンプもオフになります。\n2. 結果はロボットごとに一覧表示されます。停止しなかったロボットや保存できなかった停止があると警告が残り、「STOP 未確認」は後の STOP が応答を得るまで残ります。\n3. ゲームパッドのボタンを 設定 > ゲームパッド で STOP に割り当てられます。\n4. STOP はソフトウェアです。機械の物理的な非常停止の代わりにはなりません。",
        "1. 点击 STOP（顶部栏的红色按钮，机器人面板和页脚中也有）或按 Ctrl+Shift+空格：工作单元内的所有机器人无需确认立即停止，所有阀门和泵也会关闭。\n2. 结果按机器人逐个列出。若有机器人未停止或停止未能保存，警告会一直留在屏幕上；“STOP 未确认”会保留到之后的某次 STOP 得到应答。\n3. 可在“配置 > 手柄”中把手柄按键映射为 STOP。\n4. STOP 是软件功能，不能取代机器的物理急停。",
        "1. Prima STOP (o botão vermelho da barra superior, também no painel do robô e no rodapé) ou Ctrl+Shift+Espaço: todos os robôs da célula param de imediato, sem confirmação, e todas as válvulas e bombas desligam-se.\n2. O resultado é listado robô a robô. Fica um aviso no ecrã se um robô não parou ou se a paragem não foi guardada, e «STOP não confirmado» permanece até um STOP posterior obter resposta.\n3. Pode atribuir um botão do comando a STOP em Config > Comando.\n4. O STOP é software: não substitui a paragem de emergência física da máquina."] },
  { id: "trajectory", view: "robot", level: "basic",
    kw: ["record points|record a trajectory|save a trajectory|add point|points table|play the sequence|repeat|loop", "grabar puntos|grabar una trayectoria|guardar una trayectoria|anadir punto|tabla de puntos|reproducir la secuencia|repetir|bucle", "punkte aufnehmen|trajektorie aufnehmen|trajektorie speichern|punkt hinzufugen|punktetabelle|sequenz abspielen|wiederholen", "enregistrer des points|enregistrer une trajectoire|sauvegarder une trajectoire|ajouter un point|table de points|lire la sequence|repeter|boucle", "registrare punti|registrare una traiettoria|salvare una traiettoria|aggiungere un punto|tabella dei punti|riprodurre la sequenza|ripetere|ciclo", "ポイントを記録|軌道を記録|軌道を保存|ポイント追加|ポイント表|シーケンスを再生|繰り返", "记录点位|记录轨迹|保存轨迹|添加点|点位表|播放序列|循环", "gravar pontos|gravar uma trajetoria|guardar uma trajetoria|adicionar ponto|tabela de pontos|reproduzir a sequencia|repetir|ciclo"],
    q: ["How do I record and play a trajectory?", "¿Cómo grabo y reproduzco una trayectoria?", "Wie nehme ich eine Trajektorie auf und spiele sie ab?", "Comment enregistrer et lire une trajectoire ?", "Come registro e riproduco una traiettoria?", "軌道を記録して再生するには？", "怎么记录并播放轨迹？", "Como gravo e reproduzo uma trajetória?"],
    a: ["1. Open the robot's panel and jog it to the first pose.\n2. Press \"+ Add Point\" to capture the pose in the Points Table; repeat for every step.\n3. Reorder, edit or delete steps with the arrows, pencil and trash icons.\n4. Press Save to keep it as a Work on the server.\n5. Press Play (Repeat loops it, the Speed slider scales it). The cyan line in the 3D view previews the path.",
        "1. Abre el panel del robot y muévelo a la primera pose.\n2. Pulsa \"+ Añadir punto\" para capturar la pose en la Tabla de puntos; repite con cada paso.\n3. Reordena, edita o borra pasos con las flechas, el lápiz y la papelera.\n4. Pulsa Guardar para conservarla como Trabajo en el servidor.\n5. Pulsa Reproducir (Repetir hace bucle, el deslizador Velocidad la escala). La línea cian de la vista 3D previsualiza el recorrido.",
        "1. Das Bedienfeld des Roboters öffnen und ihn in die erste Pose fahren.\n2. \"+ Punkt hinzufügen\" drücken, um die Pose in der Punktetabelle zu speichern; für jeden Schritt wiederholen.\n3. Schritte mit Pfeilen, Stift und Papierkorb umsortieren, bearbeiten oder löschen.\n4. Speichern drücken, um sie als Arbeit auf dem Server zu behalten.\n5. Abspielen drücken (Wiederholen läuft in Schleife, der Schieberegler Geschwindigkeit skaliert). Die Cyan-Linie in der 3D-Ansicht zeigt den Weg vorab.",
        "1. Ouvrez le panneau du robot et amenez-le à la première pose.\n2. Appuyez sur « + Ajouter un point » pour capturer la pose dans la table de points ; répétez pour chaque étape.\n3. Réordonnez, modifiez ou supprimez les étapes avec les flèches, le crayon et la corbeille.\n4. Appuyez sur Enregistrer pour la garder comme Travail sur le serveur.\n5. Appuyez sur Lecture (Répéter la met en boucle, le curseur Vitesse la met à l'échelle). La ligne cyan de la vue 3D montre le trajet à l'avance.",
        "1. Apri il pannello del robot e portalo alla prima posa.\n2. Premi \"+ Aggiungi punto\" per catturare la posa nella tabella dei punti; ripeti per ogni passo.\n3. Riordina, modifica o elimina i passi con frecce, matita e cestino.\n4. Premi Salva per conservarla come Lavoro sul server.\n5. Premi Riproduci (Ripeti la mette in ciclo, il cursore Velocità la scala). La linea ciano nella vista 3D mostra in anteprima il percorso.",
        "1. ロボットのパネルを開き、最初の姿勢まで動かします。\n2. 「+ ポイント追加」を押すとその姿勢がポイント表に記録されます。ステップごとに繰り返します。\n3. 矢印・鉛筆・ゴミ箱でステップの並べ替え、編集、削除ができます。\n4. 保存を押すと、サーバーにワークとして保存されます。\n5. 再生を押します（繰り返しでループ、速度スライダーで速さを調整）。3Dビューのシアンの線で経路を事前に確認できます。",
        "1. 打开机器人面板，把它移动到第一个姿态。\n2. 点击“+ 添加点”，把该姿态记录到点位表；每一步都重复。\n3. 用箭头、铅笔和垃圾桶图标重新排序、编辑或删除步骤。\n4. 点击保存，把它作为工作文件保存到服务器。\n5. 点击播放（重复为循环，速度滑块调节快慢）。3D 视图中的青色线条可预览路径。",
        "1. Abra o painel do robô e leve-o à primeira pose.\n2. Prima \"+ Adicionar ponto\" para capturar a pose na Tabela de pontos; repita em cada passo.\n3. Reordene, edite ou apague passos com as setas, o lápis e o caixote.\n4. Prima Guardar para a manter como Trabalho no servidor.\n5. Prima Reproduzir (Repetir faz ciclo, o deslizador Velocidade escala-a). A linha ciano da vista 3D mostra o percurso antes."] },
  { id: "tool", view: "robot", level: "basic",
    kw: ["tool|end effector|gripper|solder|dispenser|screwdriver|urtc tool|valve|pump", "herramienta|efector final|pinza|soldador|dispensador|destornillador|herramienta urtc|valvula|bomba", "werkzeug|endeffektor|greifer|lotkolben|dispenser|schrauber|urtc-werkzeug|ventil|pumpe", "outil|effecteur|pince|fer a souder|doseur|visseuse|outil urtc|vanne|pompe", "utensile|effettore|pinza|saldatore|dispenser|avvitatore|utensile urtc|valvola|pompa", "ツール|エンドエフェクタ|グリッパー|はんだごて|ディスペンサー|ドライバー|バルブ|ポンプ", "工具|末端执行器|夹爪|烙铁|点胶|螺丝刀|电磁阀|泵", "ferramenta|efetuador|garra|ferro de soldar|doseador|chave de parafusos|valvula|bomba"],
    q: ["How do I choose the tool of a robot?", "¿Cómo elijo la herramienta de un robot?", "Wie wähle ich das Werkzeug eines Roboters?", "Comment choisir l'outil d'un robot ?", "Come scelgo l'utensile di un robot?", "ロボットのツールを選ぶには？", "怎么选择机器人的工具？", "Como escolho a ferramenta de um robô?"],
    a: ["1. Open the robot's panel.\n2. Use the Tool selector to assign a URTC tool (soldering iron, dispenser, screwdriver, gripper...) to the end effector.\n3. The tool shows on the 3D model's tip, and its own controls (valve, pump, temperature) appear in the panel.\n4. Modules such as XY Table, Vacuum Table or Heated Bed say \"Not Assigned\" until you enable them in Model & Tools.",
        "1. Abre el panel del robot.\n2. Usa el selector Herramienta para asignar una herramienta URTC (soldador, dispensador, destornillador, pinza...) al efector final.\n3. La herramienta aparece en la punta del modelo 3D y sus controles (válvula, bomba, temperatura) salen en el panel.\n4. Módulos como Mesa XY, Mesa de vacío o Cama caliente dicen \"No asignado\" hasta que los actives en Modelo y herramientas.",
        "1. Das Bedienfeld des Roboters öffnen.\n2. Im Werkzeug-Auswahlfeld ein URTC-Werkzeug (Lötkolben, Dispenser, Schrauber, Greifer ...) dem Endeffektor zuweisen.\n3. Das Werkzeug erscheint an der Spitze des 3D-Modells, seine Bedienelemente (Ventil, Pumpe, Temperatur) im Bedienfeld.\n4. Module wie XY-Tisch, Vakuumtisch oder Heizbett zeigen \"Nicht zugewiesen\", bis Sie sie unter Modell & Werkzeuge aktivieren.",
        "1. Ouvrez le panneau du robot.\n2. Avec le sélecteur Outil, affectez un outil URTC (fer à souder, doseur, visseuse, pince...) à l'effecteur.\n3. L'outil apparaît au bout du modèle 3D et ses commandes (vanne, pompe, température) s'affichent dans le panneau.\n4. Les modules comme Table XY, Table à vide ou Plateau chauffant affichent « Non assigné » tant que vous ne les activez pas dans Modèle et outils.",
        "1. Apri il pannello del robot.\n2. Con il selettore Utensile assegna un utensile URTC (saldatore, dispenser, avvitatore, pinza...) all'effettore.\n3. L'utensile compare sulla punta del modello 3D e i suoi comandi (valvola, pompa, temperatura) nel pannello.\n4. I moduli come Tavola XY, Tavola a vuoto o Piano riscaldato dicono \"Non assegnato\" finché non li abiliti in Modello e utensili.",
        "1. ロボットのパネルを開きます。\n2. ツールのセレクターで URTC ツール（はんだごて、ディスペンサー、ドライバー、グリッパーなど）をエンドエフェクタに割り当てます。\n3. ツールは3Dモデルの先端に表示され、バルブ・ポンプ・温度の操作がパネルに現れます。\n4. XYテーブル、真空テーブル、ヒートベッドなどのモジュールは、モデルとツールで有効にするまで「未割り当て」です。",
        "1. 打开机器人面板。\n2. 用“工具”选择器把 URTC 工具（烙铁、点胶、螺丝刀、夹爪等）分配给末端执行器。\n3. 工具会显示在 3D 模型的末端，它的控件（电磁阀、泵、温度）出现在面板中。\n4. XY 工作台、真空台、加热床等模块在“型号与工具”中启用前显示“未分配”。",
        "1. Abra o painel do robô.\n2. Com o seletor Ferramenta atribua uma ferramenta URTC (ferro de soldar, doseador, chave de parafusos, garra...) ao efetuador.\n3. A ferramenta aparece na ponta do modelo 3D e os seus controlos (válvula, bomba, temperatura) surgem no painel.\n4. Módulos como Mesa XY, Mesa de vácuo ou Cama aquecida dizem \"Não atribuído\" até os ativar em Modelo e ferramentas."] },
  { id: "camera", view: "cameras", level: "basic",
    kw: ["camera|vision|live feed|video|thermal|record a video|snapshot|photo", "camara|vision|imagen en vivo|video|termica|grabar un video|foto|captura", "kamera|bildverarbeitung|livebild|video|warmebild|video aufnehmen|foto", "camera|vision|flux en direct|video|thermique|enregistrer une video|photo", "telecamera|visione|immagine in diretta|video|termica|registrare un video|foto", "カメラ|ビジョン|ライブ映像|動画|サーモ|録画|写真", "摄像头|视觉|实时画面|视频|热成像|录像|拍照", "camara|visao|imagem em direto|video|termica|gravar um video|foto"],
    q: ["How do I see and record the cameras?", "¿Cómo veo y grabo las cámaras?", "Wie sehe und nehme ich die Kameras auf?", "Comment voir et enregistrer les caméras ?", "Come vedo e registro le telecamere?", "カメラを見て録画するには？", "怎么查看并录制摄像头？", "Como vejo e gravo as câmaras?"],
    a: ["1. Open VISION CENTER in the sidebar: up to eight live feeds side by side.\n2. Enable a camera in Config > Controllers (IP, USB or thermal MLX9064x) so it shows as connected.\n3. Press the record or snapshot button on a feed.\n4. Open the camera library (Media) to view, download or delete the photos and recordings.",
        "1. Abre CENTRO DE VISIÓN en la barra lateral: hasta ocho imágenes en vivo a la vez.\n2. Activa una cámara en Config > Controladores (IP, USB o térmica MLX9064x) para que salga como conectada.\n3. Pulsa el botón de grabar o de captura de una imagen.\n4. Abre la biblioteca de cámaras (Medios) para ver, descargar o borrar las fotos y grabaciones.",
        "1. VISION CENTER in der Seitenleiste öffnen: bis zu acht Livebilder nebeneinander.\n2. Eine Kamera unter Config > Controller aktivieren (IP, USB oder Wärmebild MLX9064x), damit sie als verbunden erscheint.\n3. Die Aufnahme- oder Foto-Taste eines Bildes drücken.\n4. Die Kamerabibliothek (Medien) öffnen, um Fotos und Aufnahmen anzusehen, herunterzuladen oder zu löschen.",
        "1. Ouvrez CENTRE DE VISION dans la barre latérale : jusqu'à huit flux en direct côte à côte.\n2. Activez une caméra dans Config > Contrôleurs (IP, USB ou thermique MLX9064x) pour qu'elle apparaisse connectée.\n3. Appuyez sur le bouton d'enregistrement ou de photo d'un flux.\n4. Ouvrez la bibliothèque des caméras (Médias) pour voir, télécharger ou supprimer photos et enregistrements.",
        "1. Apri CENTRO DI VISIONE nella barra laterale: fino a otto immagini in diretta affiancate.\n2. Abilita una telecamera in Config > Controller (IP, USB o termica MLX9064x) perché risulti connessa.\n3. Premi il pulsante di registrazione o di foto di un'immagine.\n4. Apri la libreria delle telecamere (Media) per vedere, scaricare o eliminare foto e registrazioni.",
        "1. サイドバーのビジョンセンターを開きます。最大8つのライブ映像を並べて表示できます。\n2. 設定 > コントローラでカメラ（IP、USB、サーモ MLX9064x）を有効にし、接続済みと表示させます。\n3. 映像の録画または写真ボタンを押します。\n4. カメラライブラリ（メディア）で写真と録画を表示・ダウンロード・削除できます。",
        "1. 打开侧边栏的“视觉中心”：最多同时显示八路实时画面。\n2. 在“配置 > 控制器”中启用摄像头（IP、USB 或热成像 MLX9064x），使其显示为已连接。\n3. 点击画面上的录像或拍照按钮。\n4. 打开摄像头库（媒体），查看、下载或删除照片和录像。",
        "1. Abra CENTRO DE VISÃO na barra lateral: até oito imagens em direto lado a lado.\n2. Ative uma câmara em Config > Controladores (IP, USB ou térmica MLX9064x) para aparecer como ligada.\n3. Prima o botão de gravar ou de foto de uma imagem.\n4. Abra a biblioteca de câmaras (Media) para ver, descarregar ou apagar fotos e gravações."] },
  { id: "flash", view: "flasher", level: "advanced",
    kw: ["flash|firmware|update the board|bootloader|can-ota|ota|upload a bin", "flashear|firmware|actualizar la placa|bootloader|can-ota|ota|subir un bin", "flashen|firmware|platine aktualisieren|bootloader|can-ota|ota|bin hochladen", "flasher|firmware|mettre a jour la carte|bootloader|can-ota|ota|televerser un bin", "flashare|firmware|aggiornare la scheda|bootloader|can-ota|ota|caricare un bin", "ファームウェア|書き込み|ボードを更新|ブートローダ|can-ota|ota", "刷写|固件|更新主板|引导程序|can-ota|ota|上传bin", "flashar|firmware|atualizar a placa|bootloader|can-ota|ota|carregar um bin"],
    q: ["How do I flash a board's firmware?", "¿Cómo flasheo el firmware de una placa?", "Wie flashe ich die Firmware einer Platine?", "Comment flasher le firmware d'une carte ?", "Come flasho il firmware di una scheda?", "ボードのファームウェアを書き込むには？", "怎么刷写主板固件？", "Como flasho o firmware de uma placa?"],
    a: ["1. In Config > CAN-OTA choose the transport. \"Hardware\" sends to the real boards; the default is a simulation that sends nothing (a banner says SIMULATION).\n2. Open Flasher (Resources > URTC), pick the board and the robot.\n3. Choose the .bin image and press Flash: pages are sent, verified with CRC32 and checked against rollback.\n4. Query the version afterwards in Tester to confirm.",
        "1. En Config > CAN-OTA elige el transporte. \"Hardware\" envía a las placas reales; el predeterminado es una simulación que no envía nada (un aviso dice SIMULACIÓN).\n2. Abre Flasher (Recursos > URTC), elige la placa y el robot.\n3. Elige la imagen .bin y pulsa Flashear: se envían las páginas, se verifican con CRC32 y se comprueba el anti-rollback.\n4. Consulta la versión después en Tester para confirmar.",
        "1. Unter Config > CAN-OTA den Transport wählen. \"Hardware\" sendet an die echten Platinen; Standard ist eine Simulation, die nichts sendet (ein Hinweis zeigt SIMULATION).\n2. Flasher (Ressourcen > URTC) öffnen, Platine und Roboter wählen.\n3. Das .bin-Image wählen und Flashen drücken: Seiten werden gesendet, mit CRC32 geprüft und gegen Rollback kontrolliert.\n4. Danach im Tester die Version abfragen, um es zu bestätigen.",
        "1. Dans Config > CAN-OTA, choisissez le transport. « Matériel » envoie aux vraies cartes ; par défaut c'est une simulation qui n'envoie rien (un bandeau indique SIMULATION).\n2. Ouvrez Flasher (Ressources > URTC), choisissez la carte et le robot.\n3. Choisissez l'image .bin et appuyez sur Flasher : les pages sont envoyées, vérifiées par CRC32 et contrôlées contre le retour en arrière.\n4. Interrogez ensuite la version dans Tester pour confirmer.",
        "1. In Config > CAN-OTA scegli il trasporto. \"Hardware\" invia alle schede reali; il predefinito è una simulazione che non invia nulla (un avviso dice SIMULAZIONE).\n2. Apri Flasher (Risorse > URTC), scegli scheda e robot.\n3. Scegli l'immagine .bin e premi Flasha: le pagine vengono inviate, verificate con CRC32 e controllate contro il rollback.\n4. Interroga poi la versione in Tester per confermare.",
        "1. 設定 > CAN-OTA でトランスポートを選びます。「ハードウェア」は実機のボードに送信します。既定は何も送らないシミュレーションです（「シミュレーション」の表示が出ます）。\n2. フラッシャー（リソース > URTC）を開き、ボードとロボットを選びます。\n3. .bin イメージを選んで書き込みを押します。ページが送信され、CRC32 で検証され、ロールバック防止も確認されます。\n4. その後テスターでバージョンを照会して確認します。",
        "1. 在“配置 > CAN-OTA”选择传输方式。“硬件”会发送到真实主板；默认是不发送任何内容的模拟（会显示“模拟”提示）。\n2. 打开刷写器（资源 > URTC），选择主板和机器人。\n3. 选择 .bin 镜像并点击刷写：分页发送，用 CRC32 校验，并检查防回滚。\n4. 之后在测试器中查询版本以确认。",
        "1. Em Config > CAN-OTA escolha o transporte. \"Hardware\" envia para as placas reais; o predefinido é uma simulação que não envia nada (um aviso diz SIMULAÇÃO).\n2. Abra o Flasher (Recursos > URTC), escolha a placa e o robô.\n3. Escolha a imagem .bin e prima Flashar: as páginas são enviadas, verificadas com CRC32 e controladas contra rollback.\n4. Consulte depois a versão no Tester para confirmar."] },
  { id: "gamepad", view: "settings", level: "basic",
    kw: ["gamepad|controller pad|joystick|bluetooth pad|game controller|map the buttons", "mando|gamepad|joystick|mando bluetooth|asignar botones|configurar el mando", "gamepad|joystick|bluetooth-controller|tasten belegen|spielcontroller", "manette|gamepad|joystick|manette bluetooth|associer les boutons", "gamepad|joystick|controller bluetooth|assegnare i pulsanti|configurare il gamepad", "ゲームパッド|ジョイスティック|ボタンの割り当て|コントローラ", "手柄|游戏手柄|摇杆|蓝牙手柄|映射按键", "comando|gamepad|joystick|comando bluetooth|atribuir botoes|configurar o comando"],
    q: ["How do I use a gamepad?", "¿Cómo uso un mando?", "Wie benutze ich ein Gamepad?", "Comment utiliser une manette ?", "Come uso un gamepad?", "ゲームパッドを使うには？", "怎么使用游戏手柄？", "Como uso um comando?"],
    a: ["1. Connect a USB gamepad, or pair a Bluetooth one (inside Config > Gamepad).\n2. Open Config > Gamepad to see the live buttons and axes.\n3. Map buttons and sticks to jog, Home, Add Point, Play and STOP.\n4. Move the sticks: the selected robot follows.",
        "1. Conecta un mando USB o empareja uno Bluetooth (dentro de Config > Mando).\n2. Abre Config > Mando para ver los botones y ejes en vivo.\n3. Asigna botones y palancas a mover, Home, Añadir punto, Reproducir y STOP.\n4. Mueve las palancas: el robot seleccionado las sigue.",
        "1. Ein USB-Gamepad anschließen oder ein Bluetooth-Gamepad koppeln (in Config > Gamepad).\n2. Config > Gamepad öffnen, um Tasten und Achsen live zu sehen.\n3. Tasten und Sticks auf Jog, Home, Punkt hinzufügen, Abspielen und STOP legen.\n4. Die Sticks bewegen: der gewählte Roboter folgt.",
        "1. Branchez une manette USB ou appairez une manette Bluetooth (dans Config > Manette).\n2. Ouvrez Config > Manette pour voir les boutons et axes en direct.\n3. Associez boutons et sticks à déplacer, Home, Ajouter un point, Lecture et STOP.\n4. Bougez les sticks : le robot sélectionné suit.",
        "1. Collega un gamepad USB o abbina uno Bluetooth (dentro Config > Gamepad).\n2. Apri Config > Gamepad per vedere pulsanti e assi in tempo reale.\n3. Assegna pulsanti e stick a muovere, Home, Aggiungi punto, Riproduci ed STOP.\n4. Muovi gli stick: il robot selezionato li segue.",
        "1. USBゲームパッドを接続するか、Bluetoothでペアリングします（設定 > ゲームパッド の中）。\n2. 設定 > ゲームパッドで、ボタンと軸のリアルタイム表示を確認します。\n3. ボタンとスティックをジョグ、ホーム、ポイント追加、再生、STOP に割り当てます。\n4. スティックを動かすと、選択中のロボットが追従します。",
        "1. 连接 USB 手柄，或配对蓝牙手柄（在“配置 > 手柄”内）。\n2. 打开“配置 > 手柄”，实时查看按键和摇杆。\n3. 把按键和摇杆映射到点动、回零、添加点、播放和 STOP。\n4. 推动摇杆：当前选中的机器人随之运动。",
        "1. Ligue um comando USB ou emparelhe um Bluetooth (dentro de Config > Comando).\n2. Abra Config > Comando para ver os botões e eixos em direto.\n3. Atribua botões e manípulos a mover, Home, Adicionar ponto, Reproduzir e STOP.\n4. Mova os manípulos: o robô selecionado acompanha."] },
  { id: "users", view: "settings", level: "advanced",
    kw: ["user|users|account|password|role|admin|operator|login|sign in", "usuario|usuarios|cuenta|contrasena|rol|administrador|operador|iniciar sesion", "benutzer|konto|passwort|rolle|administrator|bediener|anmelden", "utilisateur|compte|mot de passe|role|administrateur|operateur|connexion", "utente|utenti|account|password|ruolo|amministratore|operatore|accesso", "ユーザー|アカウント|パスワード|ロール|管理者|オペレーター|ログイン", "用户|账户|密码|角色|管理员|操作员|登录", "utilizador|conta|palavra-passe|perfil|administrador|operador|iniciar sessao"],
    q: ["How do I create users and change passwords?", "¿Cómo creo usuarios y cambio contraseñas?", "Wie lege ich Benutzer an und ändere Passwörter?", "Comment créer des utilisateurs et changer les mots de passe ?", "Come creo utenti e cambio le password?", "ユーザーを作成しパスワードを変更するには？", "怎么创建用户并修改密码？", "Como crio utilizadores e mudo palavras-passe?"],
    a: ["1. Sign in as an administrator and open Config > Users.\n2. Add an account with a user name, a password of at least 8 characters and a role: admin (settings and users) or operator (day-to-day robot operation).\n3. Change or reset a password from the same list; remove accounts that are no longer needed.\n4. Only an administrator can save settings, and only an administrator sees the cameras' access credentials.",
        "1. Inicia sesión como administrador y abre Config > Usuarios.\n2. Añade una cuenta con nombre de usuario, contraseña de al menos 8 caracteres y rol: admin (ajustes y usuarios) u operador (manejo diario de los robots).\n3. Cambia o restablece una contraseña desde la misma lista; elimina las cuentas que ya no hagan falta.\n4. Solo un administrador puede guardar ajustes y solo un administrador ve las credenciales de acceso de las cámaras.",
        "1. Als Administrator anmelden und Config > Benutzer öffnen.\n2. Ein Konto mit Benutzername, Passwort (mindestens 8 Zeichen) und Rolle anlegen: admin (Einstellungen und Benutzer) oder operator (tägliche Bedienung der Roboter).\n3. Ein Passwort in derselben Liste ändern oder zurücksetzen; nicht mehr benötigte Konten entfernen.\n4. Nur ein Administrator kann Einstellungen speichern, und nur er sieht die Zugangsdaten der Kameras.",
        "1. Connectez-vous en administrateur et ouvrez Config > Utilisateurs.\n2. Ajoutez un compte avec un nom d'utilisateur, un mot de passe d'au moins 8 caractères et un rôle : admin (réglages et utilisateurs) ou opérateur (exploitation quotidienne des robots).\n3. Changez ou réinitialisez un mot de passe depuis la même liste ; supprimez les comptes devenus inutiles.\n4. Seul un administrateur peut enregistrer les réglages, et seul lui voit les identifiants d'accès des caméras.",
        "1. Accedi come amministratore e apri Config > Utenti.\n2. Aggiungi un account con nome utente, password di almeno 8 caratteri e ruolo: admin (impostazioni e utenti) o operatore (uso quotidiano dei robot).\n3. Cambia o reimposta una password dallo stesso elenco; rimuovi gli account non più necessari.\n4. Solo un amministratore può salvare le impostazioni e solo un amministratore vede le credenziali di accesso delle telecamere.",
        "1. 管理者でログインし、設定 > ユーザーを開きます。\n2. ユーザー名、8文字以上のパスワード、ロール（admin：設定とユーザー、operator：日常のロボット操作）を指定してアカウントを追加します。\n3. 同じ一覧でパスワードの変更やリセット、不要なアカウントの削除ができます。\n4. 設定を保存できるのは管理者だけで、カメラのアクセス認証情報が見えるのも管理者だけです。",
        "1. 以管理员身份登录，打开“配置 > 用户”。\n2. 添加账户：用户名、至少 8 个字符的密码，以及角色：admin（设置和用户）或 operator（日常机器人操作）。\n3. 在同一列表中修改或重置密码，删除不再需要的账户。\n4. 只有管理员可以保存设置，也只有管理员能看到摄像头的访问凭据。",
        "1. Inicie sessão como administrador e abra Config > Utilizadores.\n2. Adicione uma conta com nome de utilizador, palavra-passe de pelo menos 8 caracteres e perfil: admin (definições e utilizadores) ou operador (operação diária dos robôs).\n3. Mude ou reponha uma palavra-passe na mesma lista; remova as contas que já não são precisas.\n4. Só um administrador pode guardar definições e só um administrador vê as credenciais de acesso das câmaras."] },
  { id: "language", view: "settings", level: "basic",
    kw: ["language|translate|theme|change the language|portuguese|spanish|german", "idioma|traducir|tema|cambiar el idioma|portugues|espanol|aleman", "sprache|ubersetzen|thema|sprache andern|portugiesisch|spanisch", "langue|traduire|theme|changer la langue|portugais|espagnol|allemand", "lingua|tradurre|tema|cambiare la lingua|portoghese|spagnolo|tedesco", "言語|翻訳|テーマ|言語を変更|ポルトガル語", "语言|翻译|主题|切换语言|葡萄牙语|西班牙语", "idioma|traduzir|tema|mudar o idioma|portugues|espanhol|alemao"],
    q: ["How do I change the language?", "¿Cómo cambio el idioma?", "Wie ändere ich die Sprache?", "Comment changer la langue ?", "Come cambio la lingua?", "言語を変更するには？", "怎么切换语言？", "Como mudo o idioma?"],
    a: ["1. Open Config > UI & Themes.\n2. Pick the language: English, Spanish, German, French, Italian, Chinese, Japanese or Portuguese.\n3. The interface, this Help and the assistant change at once; the choice is saved on the server.",
        "1. Abre Config > Interfaz y temas.\n2. Elige el idioma: inglés, español, alemán, francés, italiano, chino, japonés o portugués.\n3. La interfaz, esta Ayuda y el asistente cambian al instante; la elección se guarda en el servidor.",
        "1. Config > Oberfläche & Themen öffnen.\n2. Die Sprache wählen: Englisch, Spanisch, Deutsch, Französisch, Italienisch, Chinesisch, Japanisch oder Portugiesisch.\n3. Oberfläche, diese Hilfe und der Assistent wechseln sofort; die Wahl wird auf dem Server gespeichert.",
        "1. Ouvrez Config > Interface et thèmes.\n2. Choisissez la langue : anglais, espagnol, allemand, français, italien, chinois, japonais ou portugais.\n3. L'interface, cette Aide et l'assistant changent aussitôt ; le choix est enregistré sur le serveur.",
        "1. Apri Config > Interfaccia e temi.\n2. Scegli la lingua: inglese, spagnolo, tedesco, francese, italiano, cinese, giapponese o portoghese.\n3. Interfaccia, questa Guida e l'assistente cambiano subito; la scelta è salvata sul server.",
        "1. 設定 > UI とテーマを開きます。\n2. 言語を選びます：英語、スペイン語、ドイツ語、フランス語、イタリア語、中国語、日本語、ポルトガル語。\n3. 画面、このヘルプ、アシスタントがすぐに切り替わり、選択はサーバーに保存されます。",
        "1. 打开“配置 > 界面与主题”。\n2. 选择语言：英语、西班牙语、德语、法语、意大利语、中文、日语或葡萄牙语。\n3. 界面、本帮助和助手会立即切换；选择会保存在服务器上。",
        "1. Abra Config > Interface e temas.\n2. Escolha o idioma: inglês, espanhol, alemão, francês, italiano, chinês, japonês ou português.\n3. A interface, esta Ajuda e o assistente mudam de imediato; a escolha fica guardada no servidor."] },
  { id: "remote", view: "settings", level: "advanced",
    kw: ["phone|android|ios|tablet|remote access|from another device|from the phone|wear os|watch", "telefono|movil|android|ios|tableta|acceso remoto|desde otro dispositivo|reloj", "handy|smartphone|android|ios|tablet|fernzugriff|anderes gerat|uhr", "telephone|mobile|android|ios|tablette|acces a distance|autre appareil|montre", "telefono|cellulare|android|ios|tablet|accesso remoto|altro dispositivo|orologio", "スマホ|電話|android|ios|タブレット|リモートアクセス|別のデバイス|ウォッチ", "手机|安卓|ios|平板|远程访问|其他设备|手表", "telemovel|android|ios|tablet|acesso remoto|outro dispositivo|relogio"],
    q: ["Can I use it from my phone or watch?", "¿Puedo usarlo desde el móvil o el reloj?", "Kann ich es vom Handy oder von der Uhr aus nutzen?", "Puis-je l'utiliser depuis mon téléphone ou ma montre ?", "Posso usarlo dal telefono o dall'orologio?", "スマホやウォッチから使えますか？", "能用手机或手表使用吗？", "Posso usar a partir do telemóvel ou do relógio?"],
    a: ["1. Every client talks to the same server: this web app, the Android and iOS control apps, the DSI touch screen, the desktop SUITE and the WearOS watch.\n2. On the phone, open the app and let it discover the server (mDNS), or type the server's address and port.\n3. Sign in with the same account; the robots, trajectories and settings are the same everywhere.\n4. Outside your own network use a VPN or HTTPS (see the remote-access guide), never an open port without TLS.",
        "1. Todos los clientes hablan con el mismo servidor: esta app web, las apps de control Android e iOS, la pantalla táctil DSI, la SUITE de escritorio y el reloj WearOS.\n2. En el móvil abre la app y deja que descubra el servidor (mDNS), o escribe su dirección y puerto.\n3. Inicia sesión con la misma cuenta; los robots, trayectorias y ajustes son los mismos en todas partes.\n4. Fuera de tu red usa una VPN o HTTPS (mira la guía de acceso remoto), nunca un puerto abierto sin TLS.",
        "1. Alle Clients sprechen mit demselben Server: diese Web-App, die Android- und iOS-Steuer-Apps, der DSI-Touchscreen, die Desktop-SUITE und die WearOS-Uhr.\n2. Auf dem Handy die App öffnen und den Server finden lassen (mDNS) oder Adresse und Port eintippen.\n3. Mit demselben Konto anmelden; Roboter, Trajektorien und Einstellungen sind überall gleich.\n4. Außerhalb des eigenen Netzes ein VPN oder HTTPS verwenden (siehe Fernzugriffs-Anleitung), nie einen offenen Port ohne TLS.",
        "1. Tous les clients parlent au même serveur : cette application web, les applis de commande Android et iOS, l'écran tactile DSI, la SUITE de bureau et la montre WearOS.\n2. Sur le téléphone, ouvrez l'appli et laissez-la découvrir le serveur (mDNS), ou saisissez son adresse et son port.\n3. Connectez-vous avec le même compte ; robots, trajectoires et réglages sont les mêmes partout.\n4. Hors de votre réseau, utilisez un VPN ou HTTPS (voir le guide d'accès à distance), jamais un port ouvert sans TLS.",
        "1. Tutti i client parlano con lo stesso server: questa app web, le app di controllo Android e iOS, lo schermo tattile DSI, la SUITE desktop e l'orologio WearOS.\n2. Sul telefono apri l'app e lascia che scopra il server (mDNS), oppure scrivi indirizzo e porta.\n3. Accedi con lo stesso account; robot, traiettorie e impostazioni sono uguali ovunque.\n4. Fuori dalla tua rete usa una VPN o HTTPS (vedi la guida all'accesso remoto), mai una porta aperta senza TLS.",
        "1. すべてのクライアントは同じサーバーに接続します：このWebアプリ、Android／iOS制御アプリ、DSIタッチ画面、デスクトップSUITE、WearOSウォッチ。\n2. スマホでアプリを開き、サーバーを自動検出（mDNS）させるか、アドレスとポートを入力します。\n3. 同じアカウントでログインします。ロボット、軌道、設定はどこでも同じです。\n4. 自分のネットワーク外ではVPNかHTTPSを使い（リモートアクセスガイド参照）、TLSなしでポートを開放しないでください。",
        "1. 所有客户端都连接同一台服务器：这个网页应用、Android 和 iOS 控制应用、DSI 触摸屏、桌面 SUITE 以及 WearOS 手表。\n2. 在手机上打开应用，让它自动发现服务器（mDNS），或输入服务器地址和端口。\n3. 用同一账户登录；机器人、轨迹和设置在各处都一致。\n4. 在自己的网络之外请使用 VPN 或 HTTPS（见远程访问指南），切勿在没有 TLS 的情况下开放端口。",
        "1. Todos os clientes falam com o mesmo servidor: esta aplicação web, as apps de controlo Android e iOS, o ecrã tátil DSI, a SUITE de ambiente de trabalho e o relógio WearOS.\n2. No telemóvel abra a app e deixe-a descobrir o servidor (mDNS), ou escreva o endereço e a porta.\n3. Inicie sessão com a mesma conta; os robôs, trajetórias e definições são os mesmos em todo o lado.\n4. Fora da sua rede use uma VPN ou HTTPS (veja o guia de acesso remoto), nunca uma porta aberta sem TLS."] },
  { id: "server", view: "adminServer", level: "advanced",
    kw: ["server|restart the server|shutdown|reboot|logs|connected devices|clients|port", "servidor|reiniciar el servidor|apagar|reiniciar|registros|dispositivos conectados|clientes|puerto", "server|server neu starten|herunterfahren|neustart|protokolle|verbundene gerate|clients|port", "serveur|redemarrer le serveur|eteindre|redemarrer|journaux|appareils connectes|clients|port", "server|riavviare il server|spegnere|riavvio|log|dispositivi connessi|client|porta", "サーバー|サーバーを再起動|シャットダウン|再起動|ログ|接続中のデバイス|ポート", "服务器|重启服务器|关机|重启|日志|已连接设备|客户端|端口", "servidor|reiniciar o servidor|desligar|reiniciar|registos|dispositivos ligados|clientes|porta"],
    q: ["How do I restart the server or read its log?", "¿Cómo reinicio el servidor o leo su registro?", "Wie starte ich den Server neu oder lese sein Protokoll?", "Comment redémarrer le serveur ou lire son journal ?", "Come riavvio il server o leggo il suo log?", "サーバーを再起動したりログを読むには？", "怎么重启服务器或查看日志？", "Como reinicio o servidor ou leio o seu registo?"],
    a: ["1. Open Server Admin in the HYDRA-UMC menu (administrators only).\n2. Clients lists the devices connected now; Logs shows the server's own log.\n3. Server changes the port or name and has \"Restart server now\".\n4. Shutdown and restart of the whole computer are only accepted from the machine itself (its own screen), never through a proxy or from another site.",
        "1. Abre Administrar servidor en el menú HYDRA-UMC (solo administradores).\n2. Clientes lista los dispositivos conectados ahora; Registros muestra el log del propio servidor.\n3. Servidor cambia el puerto o el nombre y tiene \"Reiniciar servidor ahora\".\n4. Apagar y reiniciar todo el equipo solo se aceptan desde la propia máquina (su pantalla), nunca a través de un proxy ni desde otra web.",
        "1. Serveradmin im HYDRA-UMC-Menü öffnen (nur Administratoren).\n2. Clients listet die aktuell verbundenen Geräte; Protokolle zeigt das Log des Servers selbst.\n3. Server ändert Port oder Namen und hat \"Server jetzt neu starten\".\n4. Herunterfahren und Neustart des ganzen Rechners werden nur von der Maschine selbst (ihrem Bildschirm) akzeptiert, nie über einen Proxy oder von einer anderen Seite.",
        "1. Ouvrez Admin serveur dans le menu HYDRA-UMC (administrateurs seulement).\n2. Clients liste les appareils connectés en ce moment ; Journaux montre le journal du serveur lui-même.\n3. Serveur change le port ou le nom et propose « Redémarrer le serveur maintenant ».\n4. L'arrêt et le redémarrage de tout l'ordinateur ne sont acceptés que depuis la machine elle-même (son écran), jamais via un proxy ni depuis un autre site.",
        "1. Apri Admin server nel menu HYDRA-UMC (solo amministratori).\n2. Client elenca i dispositivi connessi ora; Log mostra il log del server stesso.\n3. Server cambia porta o nome e ha \"Riavvia il server ora\".\n4. Spegnimento e riavvio dell'intero computer sono accettati solo dalla macchina stessa (il suo schermo), mai tramite proxy né da un altro sito.",
        "1. HYDRA-UMC メニューのサーバー管理を開きます（管理者のみ）。\n2. クライアントは現在接続中のデバイスを、ログはサーバー自身のログを表示します。\n3. サーバーではポートや名前を変更でき、「今すぐサーバーを再起動」があります。\n4. コンピューター全体のシャットダウンと再起動は、そのマシン自身（本体の画面）からのみ受け付けられ、プロキシや他のサイト経由では受け付けられません。",
        "1. 在 HYDRA-UMC 菜单中打开“服务器管理”（仅管理员）。\n2. “客户端”列出当前连接的设备；“日志”显示服务器自身的日志。\n3. “服务器”可更改端口或名称，并有“立即重启服务器”。\n4. 整机关机和重启只接受来自本机自身（其屏幕）的请求，绝不接受经代理或来自其他网站的请求。",
        "1. Abra Admin do servidor no menu HYDRA-UMC (só administradores).\n2. Clientes lista os dispositivos ligados agora; Registos mostra o log do próprio servidor.\n3. Servidor muda a porta ou o nome e tem \"Reiniciar servidor agora\".\n4. Desligar e reiniciar todo o computador só são aceites a partir da própria máquina (o seu ecrã), nunca através de um proxy nem de outro site."] },
  { id: "works", view: "robot", level: "advanced",
    kw: ["work|works|saved trajectories|upload a file|download a file|example|json", "trabajo|trabajos|trayectorias guardadas|subir un archivo|descargar un archivo|ejemplo|json", "arbeit|arbeiten|gespeicherte trajektorien|datei hochladen|datei herunterladen|beispiel|json", "travail|travaux|trajectoires enregistrees|televerser un fichier|telecharger un fichier|exemple|json", "lavoro|lavori|traiettorie salvate|caricare un file|scaricare un file|esempio|json", "ワーク|保存した軌道|ファイルをアップロード|ダウンロード|サンプル|json", "工作文件|已保存轨迹|上传文件|下载文件|示例|json", "trabalho|trabalhos|trajetorias guardadas|carregar um ficheiro|descarregar um ficheiro|exemplo|json"],
    q: ["Where are my saved trajectories?", "¿Dónde están mis trayectorias guardadas?", "Wo sind meine gespeicherten Trajektorien?", "Où sont mes trajectoires enregistrées ?", "Dove sono le mie traiettorie salvate?", "保存した軌道はどこにありますか？", "我保存的轨迹在哪里？", "Onde estão as minhas trajetórias guardadas?"],
    a: ["1. Saved trajectories are \"Works\": JSON files stored per robot in the server's data/WORKS folder.\n2. In the robot's panel use the Works selector to load one, or upload a file from your computer.\n3. Load a canned Example (circles, spirals, pick-and-place...) to start: it is converted and re-solved for the selected robot model.\n4. Where each robot's Works are stored can be changed in Config > Work Paths.",
        "1. Las trayectorias guardadas son \"Trabajos\": archivos JSON por robot en la carpeta data/WORKS del servidor.\n2. En el panel del robot usa el selector de Trabajos para cargar uno, o sube un archivo desde tu ordenador.\n3. Carga un Ejemplo (círculos, espirales, pick and place...) para empezar: se convierte y se resuelve de nuevo para el modelo de robot seleccionado.\n4. Dónde se guardan los Trabajos de cada robot se cambia en Config > Rutas de trabajo.",
        "1. Gespeicherte Trajektorien sind \"Arbeiten\": JSON-Dateien pro Roboter im Ordner data/WORKS des Servers.\n2. Im Bedienfeld des Roboters mit der Arbeiten-Auswahl eine laden oder eine Datei vom Rechner hochladen.\n3. Zum Start ein Beispiel laden (Kreise, Spiralen, Pick-and-Place ...): es wird für das gewählte Robotermodell umgerechnet und neu gelöst.\n4. Wo die Arbeiten jedes Roboters liegen, ändern Sie unter Config > Arbeitspfade.",
        "1. Les trajectoires enregistrées sont des « Travaux » : fichiers JSON par robot dans le dossier data/WORKS du serveur.\n2. Dans le panneau du robot, utilisez le sélecteur de Travaux pour en charger un, ou téléversez un fichier depuis votre ordinateur.\n3. Chargez un Exemple (cercles, spirales, pick-and-place...) pour commencer : il est converti et recalculé pour le modèle de robot choisi.\n4. L'emplacement des Travaux de chaque robot se change dans Config > Chemins de travail.",
        "1. Le traiettorie salvate sono \"Lavori\": file JSON per robot nella cartella data/WORKS del server.\n2. Nel pannello del robot usa il selettore Lavori per caricarne uno, o carica un file dal tuo computer.\n3. Carica un Esempio (cerchi, spirali, pick and place...) per iniziare: viene convertito e risolto di nuovo per il modello di robot scelto.\n4. Dove sono salvati i Lavori di ogni robot si cambia in Config > Percorsi di lavoro.",
        "1. 保存した軌道は「ワーク」です。サーバーの data/WORKS フォルダーにロボットごとの JSON ファイルとして保存されます。\n2. ロボットのパネルのワーク選択で読み込むか、パソコンからファイルをアップロードします。\n3. まずサンプル（円、らせん、ピック＆プレースなど）を読み込んでみてください。選択中のロボットモデル向けに変換・再計算されます。\n4. 各ロボットのワークの保存先は 設定 > ワークパス で変更できます。",
        "1. 已保存的轨迹称为“工作文件”：按机器人保存在服务器 data/WORKS 文件夹中的 JSON 文件。\n2. 在机器人面板用“工作文件”选择器加载，或从电脑上传文件。\n3. 先加载一个示例（圆、螺旋、取放等）：它会针对当前选中的机器人型号转换并重新求解。\n4. 每个机器人工作文件的存放位置可在“配置 > 工作路径”更改。",
        "1. As trajetórias guardadas são \"Trabalhos\": ficheiros JSON por robô na pasta data/WORKS do servidor.\n2. No painel do robô use o seletor de Trabalhos para carregar um, ou carregue um ficheiro do seu computador.\n3. Carregue um Exemplo (círculos, espirais, pick and place...) para começar: é convertido e resolvido de novo para o modelo de robô escolhido.\n4. Onde ficam os Trabalhos de cada robô muda-se em Config > Caminhos de trabalho."] },
  { id: "simulation", view: "flasher", level: "technical",
    kw: ["simulation|simulated|mock|is it real|not real|nothing happens", "simulacion|simulado|es real|no es real|no pasa nada", "simulation|simuliert|ist es echt|nichts passiert", "simulation|simule|est ce reel|rien ne se passe", "simulazione|simulato|e reale|non succede nulla", "シミュレーション|模擬|本物ですか|何も起こらない", "模拟|仿真|是真的吗|没有反应", "simulacao|simulado|e real|nao acontece nada"],
    q: ["Why does it say SIMULATION?", "¿Por qué dice SIMULACIÓN?", "Warum steht dort SIMULATION?", "Pourquoi est-il écrit SIMULATION ?", "Perché dice SIMULAZIONE?", "なぜ「シミュレーション」と表示されるのですか？", "为什么显示“模拟”？", "Porque é que diz SIMULAÇÃO?"],
    a: ["1. The CAN-OTA transport is set to the simulated one: it walks through the whole flashing sequence but sends nothing to any board.\n2. A simulated flash never changes the firmware version that is saved for the board.\n3. To flash for real set Config > CAN-OTA > transport to Hardware.\n4. Tiers that have no relay tunnel yet (URTC head and expansion) say so instead of pretending.",
        "1. El transporte CAN-OTA está en el simulado: recorre toda la secuencia de flasheo pero no envía nada a ninguna placa.\n2. Un flasheo simulado nunca cambia la versión de firmware guardada de la placa.\n3. Para flashear de verdad pon Config > CAN-OTA > transporte en Hardware.\n4. Los niveles que aún no tienen túnel de relay (cabezal URTC y expansión) lo dicen en vez de fingir.",
        "1. Der CAN-OTA-Transport steht auf dem simulierten: er durchläuft die ganze Flash-Sequenz, sendet aber nichts an eine Platine.\n2. Ein simuliertes Flashen ändert nie die für die Platine gespeicherte Firmware-Version.\n3. Zum echten Flashen Config > CAN-OTA > Transport auf Hardware stellen.\n4. Ebenen ohne Relay-Tunnel (URTC-Kopf und Erweiterung) sagen das, statt etwas vorzutäuschen.",
        "1. Le transport CAN-OTA est sur le mode simulé : il déroule toute la séquence de flashage mais n'envoie rien à aucune carte.\n2. Un flashage simulé ne modifie jamais la version de firmware enregistrée pour la carte.\n3. Pour flasher réellement, réglez Config > CAN-OTA > transport sur Matériel.\n4. Les niveaux sans tunnel de relais (tête URTC et extension) le disent au lieu de faire semblant.",
        "1. Il trasporto CAN-OTA è quello simulato: percorre tutta la sequenza di flashing ma non invia nulla a nessuna scheda.\n2. Un flashing simulato non cambia mai la versione firmware salvata per la scheda.\n3. Per flashare davvero imposta Config > CAN-OTA > trasporto su Hardware.\n4. I livelli senza tunnel di relay (testa URTC ed espansione) lo dicono invece di fingere.",
        "1. CAN-OTA のトランスポートがシミュレーションになっています。書き込みの手順は最後まで進みますが、ボードには何も送信されません。\n2. シミュレーションの書き込みでは、ボードに保存されたファームウェアバージョンは変わりません。\n3. 実際に書き込むには 設定 > CAN-OTA > トランスポート を ハードウェア にします。\n4. リレートンネルがまだない階層（URTC ヘッドと拡張）は、ごまかさずにその旨を表示します。",
        "1. CAN-OTA 传输被设为模拟：会走完整个刷写流程，但不会向任何主板发送内容。\n2. 模拟刷写绝不会改变已为该主板保存的固件版本。\n3. 要真实刷写，请把“配置 > CAN-OTA > 传输”设为硬件。\n4. 尚无中继隧道的层级（URTC 头和扩展）会如实说明，而不是假装可用。",
        "1. O transporte CAN-OTA está no simulado: percorre toda a sequência de flash mas não envia nada a nenhuma placa.\n2. Um flash simulado nunca altera a versão de firmware guardada para a placa.\n3. Para flashar a sério ponha Config > CAN-OTA > transporte em Hardware.\n4. Os níveis que ainda não têm túnel de relay (cabeça URTC e expansão) dizem-no em vez de fingir."] },
  { id: "security", view: "adminServer", level: "technical",
    kw: ["security|token|https|tls|certificate|secure|camera password|ticket", "seguridad|token|https|tls|certificado|seguro|contrasena de la camara|ticket", "sicherheit|token|https|tls|zertifikat|sicher|kamerapasswort|ticket", "securite|jeton|https|tls|certificat|securise|mot de passe de la camera|ticket", "sicurezza|token|https|tls|certificato|sicuro|password della telecamera|ticket", "セキュリティ|トークン|https|tls|証明書|安全|カメラのパスワード|チケット", "安全|令牌|https|tls|证书|安全性|摄像头密码|票据", "seguranca|token|https|tls|certificado|seguro|palavra-passe da camara|ticket"],
    q: ["How is access to the server protected?", "¿Cómo se protege el acceso al servidor?", "Wie ist der Zugriff auf den Server geschützt?", "Comment l'accès au serveur est-il protégé ?", "Come è protetto l'accesso al server?", "サーバーへのアクセスはどう保護されていますか？", "服务器的访问是如何保护的？", "Como é protegido o acesso ao servidor?"],
    a: ["1. Every write and the live connection need a signed-in session; the token rides in the WebSocket subprotocol, not in the address.\n2. Camera pictures and recordings are opened with a short-lived ticket when the server asks for it (HYDRA_UMC_CAMERA_AUTH=required).\n3. Camera access credentials are only sent to administrators.\n4. For use outside a trusted LAN enable HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) and set a real JWT_SECRET.",
        "1. Toda escritura y la conexión en vivo necesitan una sesión iniciada; el token viaja en el subprotocolo del WebSocket, no en la dirección.\n2. Las imágenes y grabaciones de las cámaras se abren con un ticket de vida corta cuando el servidor lo exige (HYDRA_UMC_CAMERA_AUTH=required).\n3. Las credenciales de acceso a las cámaras solo se envían a administradores.\n4. Para usarlo fuera de una LAN de confianza activa HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) y define un JWT_SECRET real.",
        "1. Jedes Schreiben und die Live-Verbindung brauchen eine angemeldete Sitzung; das Token reist im WebSocket-Subprotokoll, nicht in der Adresse.\n2. Kamerabilder und -aufnahmen werden mit einem kurzlebigen Ticket geöffnet, wenn der Server es verlangt (HYDRA_UMC_CAMERA_AUTH=required).\n3. Die Zugangsdaten der Kameras gehen nur an Administratoren.\n4. Außerhalb eines vertrauenswürdigen LANs HTTPS aktivieren (TLS_CERT_PATH / TLS_KEY_PATH) und ein echtes JWT_SECRET setzen.",
        "1. Toute écriture et la connexion en direct exigent une session ouverte ; le jeton circule dans le sous-protocole WebSocket, pas dans l'adresse.\n2. Les images et enregistrements des caméras s'ouvrent avec un ticket de courte durée quand le serveur l'exige (HYDRA_UMC_CAMERA_AUTH=required).\n3. Les identifiants d'accès des caméras ne sont envoyés qu'aux administrateurs.\n4. Hors d'un LAN de confiance, activez HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) et définissez un vrai JWT_SECRET.",
        "1. Ogni scrittura e la connessione in tempo reale richiedono una sessione attiva; il token viaggia nel sottoprotocollo WebSocket, non nell'indirizzo.\n2. Immagini e registrazioni delle telecamere si aprono con un ticket di breve durata quando il server lo richiede (HYDRA_UMC_CAMERA_AUTH=required).\n3. Le credenziali di accesso alle telecamere sono inviate solo agli amministratori.\n4. Fuori da una LAN fidata abilita HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) e imposta un vero JWT_SECRET.",
        "1. すべての書き込みとライブ接続にはログイン済みセッションが必要です。トークンはアドレスではなく WebSocket のサブプロトコルで送られます。\n2. サーバーが要求する場合（HYDRA_UMC_CAMERA_AUTH=required）、カメラの映像と録画は短寿命のチケットで開きます。\n3. カメラのアクセス認証情報は管理者にだけ送られます。\n4. 信頼できるLANの外で使うときは HTTPS（TLS_CERT_PATH / TLS_KEY_PATH）を有効にし、本物の JWT_SECRET を設定してください。",
        "1. 所有写入操作和实时连接都需要已登录的会话；令牌通过 WebSocket 子协议传输，而不是放在地址里。\n2. 当服务器要求时（HYDRA_UMC_CAMERA_AUTH=required），摄像头画面和录像使用短时效票据打开。\n3. 摄像头的访问凭据只发送给管理员。\n4. 在可信局域网之外使用时，请启用 HTTPS（TLS_CERT_PATH / TLS_KEY_PATH）并设置真实的 JWT_SECRET。",
        "1. Toda a escrita e a ligação em direto precisam de uma sessão iniciada; o token viaja no subprotocolo do WebSocket, não no endereço.\n2. As imagens e gravações das câmaras abrem-se com um ticket de vida curta quando o servidor o exige (HYDRA_UMC_CAMERA_AUTH=required).\n3. As credenciais de acesso às câmaras só são enviadas a administradores.\n4. Fora de uma LAN de confiança ative o HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) e defina um JWT_SECRET real."] },
];
